```json
{
  "version": 1,
  "taskId": "64e61d47-08d0-4d92-9f14-491fc2a736fd",
  "commandId": "write-1",
  "operation": "run",
  "headSha": "a4bf6e68d1ec87f6ea1faaf321505c380d437763",
  "timeoutSeconds": 120,
  "command": "mkdir -p apps/mobile/src/components apps/mobile/src/screens && cat > apps/mobile/src/components/Tick.tsx <<'EOF'
import { Text, StyleSheet } from 'react-native';
import { theme } from '../theme';

export type MessageStatus = 'sending' | 'sent' | 'delivered' | 'read';

type TickProps = {
  status?: MessageStatus;
};

/** One/two checkmarks: muted by default, accent when read (Telegram-style). */
export function Tick({ status }: TickProps) {
  if (!status || status === 'sending') {
    return null;
  }

  const isRead = status === 'read';
  const double = status === 'delivered' || status === 'read';

  return (
    <Text
      style={[
        styles.tick,
        { color: isRead ? theme.colors.accent : theme.colors.muted },
      ]}
    >
      {double ? '✓✓' : '✓'}
    </Text>
  );
}

const styles = StyleSheet.create({
  tick: {
    fontSize: theme.typography.time.fontSize,
    marginLeft: 4,
    lineHeight: 14,
  },
});
EOF"
}
